CREATE TABLE capacities(id uuid PRIMARY KEY,revision integer NOT NULL DEFAULT 1,name text NOT NULL,site text NOT NULL,capacity_m3 numeric(18,3) NOT NULL CHECK(capacity_m3>=0),utilized_m3 numeric(18,3) NOT NULL CHECK(utilized_m3>=0),monthly_operating_cost numeric(18,3) NOT NULL CHECK(monthly_operating_cost>=0),currency text NOT NULL CHECK(currency ~ '^[A-Z]{3}$'),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),available_m3 numeric(18,3) GENERATED ALWAYS AS(capacity_m3-utilized_m3) STORED,CHECK(utilized_m3<=capacity_m3));
CREATE TABLE storage_requirements(id uuid PRIMARY KEY,revision integer NOT NULL DEFAULT 1,name text NOT NULL,site text NOT NULL,required_m3 numeric(18,3) NOT NULL CHECK(required_m3>=0),utilized_m3 numeric(18,3) NOT NULL CHECK(utilized_m3>=0),monthly_external_cost numeric(18,3) NOT NULL CHECK(monthly_external_cost>=0),currency text NOT NULL CHECK(currency ~ '^[A-Z]{3}$'),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE warehouse_assets(id uuid PRIMARY KEY,revision integer NOT NULL DEFAULT 1,name text NOT NULL,site text NOT NULL,capacity_m3 numeric(18,3) NOT NULL CHECK(capacity_m3>=0),utilized_m3 numeric(18,3) NOT NULL CHECK(utilized_m3>=0),monthly_operating_cost numeric(18,3) NOT NULL CHECK(monthly_operating_cost>=0),currency text NOT NULL CHECK(currency ~ '^[A-Z]{3}$'),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),available_m3 numeric(18,3) GENERATED ALWAYS AS(capacity_m3-utilized_m3) STORED,CHECK(utilized_m3<=capacity_m3));
